<?php require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/mailer.php';require_admin();$msg=$_SESSION['flash']??'';$error=$_SESSION['flash_error']??'';unset($_SESSION['flash'],$_SESSION['flash_error']);function money(string $v):float{return(float)str_replace(',','.',str_replace('.','',$v));}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';try{
 if($a==='company'){$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',iconv('UTF-8','ASCII//TRANSLIT',$_POST['name'])),'-'));$pdo->prepare("INSERT INTO companies(name,slug,status) VALUES(?,?,'active')")->execute([trim($_POST['name']),$slug]);$msg='Empresa cadastrada.';}
 if($a==='new_contract'){$pdo->prepare("INSERT INTO contracts(company_id,name,monthly_hours,base_amount,excess_hour_amount,renewal_day,cumulative,status) VALUES(?,?,?,?,?,?,?,'active')")->execute([(int)$_POST['company_id'],trim($_POST['name']),(float)str_replace(',','.',$_POST['hours']),money($_POST['base']),money($_POST['excess']),max(1,min(28,(int)$_POST['renewal_day'])),isset($_POST['cumulative'])?1:0]);$msg='Contrato cadastrado.';}
 if($a==='user'){$pdo->prepare("INSERT INTO users(company_id,name,email,password_hash,role,status) VALUES(?,?,?,?,?,'active')")->execute([(int)$_POST['company_id'],trim($_POST['name']),strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),'client']);$msg='Usuário criado.';}
 if($a==='edit_user'){$id=(int)$_POST['id'];$companyId=(int)$_POST['company_id'];$name=trim((string)$_POST['name']);$email=strtolower(trim((string)$_POST['email']));if($id<1||$companyId<1||$name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Exception('Dados inválidos.');$st=$pdo->prepare("SELECT id FROM companies WHERE id=? AND status='active'");$st->execute([$companyId]);if(!$st->fetch())throw new Exception('Empresa indisponível.');$pdo->prepare("UPDATE users SET company_id=?,name=?,email=? WHERE id=? AND role='client'")->execute([$companyId,$name,$email,$id]);audit('user_updated','user',$id,'Empresa vinculada: '.$companyId);$msg='Usuário atualizado.';}
 if($a==='toggle_user'){$pdo->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE id=? AND role='client'")->execute([(int)$_POST['id']]);$msg='Situação do usuário alterada.';}
 if($a==='reset_password'){if(strlen($_POST['password'])<12)throw new Exception('A senha deve ter ao menos 12 caracteres.');$pdo->prepare("UPDATE users SET password_hash=? WHERE id=? AND role='client'")->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),(int)$_POST['id']]);$msg='Senha provisória atualizada.';}
 if($a==='send_access'){$st=$pdo->prepare("SELECT id,name,email FROM users WHERE id=? AND role='client' AND status='active'");$st->execute([(int)$_POST['id']]);$target=$st->fetch();if(!$target)throw new Exception('Usuário indisponível.');$token=bin2hex(random_bytes(32));$pdo->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$target['id']]);$pdo->prepare('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 60 MINUTE))')->execute([$target['id'],hash('sha256',$token)]);$link='https://newsiga.com.br'.url('redefinir-senha.php?token='.$token);send_portal_mail($target['email'],$target['name'],'Seu acesso à Área do Cliente | Newsiga',recovery_email($target['name'],$link));audit('access_email_sent','user',(int)$target['id']);$msg='E-mail de acesso enviado.';}
 if($a==='contract'){$pdo->prepare('UPDATE contracts SET monthly_hours=?,base_amount=?,excess_hour_amount=?,renewal_day=?,cumulative=? WHERE id=?')->execute([(float)str_replace(',','.',$_POST['hours']),money($_POST['base']),money($_POST['excess']),max(1,min(28,(int)$_POST['renewal_day'])),isset($_POST['cumulative'])?1:0,(int)$_POST['id']]);$msg='Contrato atualizado.';}
 if($a==='delete_contract'){$pdo->prepare('DELETE FROM contracts WHERE id=?')->execute([(int)$_POST['id']]);$msg='Contrato excluído.';}
 $_SESSION['flash']=$msg;
}catch(Throwable $e){$_SESSION['flash_error']=$e instanceof PDOException&&$e->getCode()==='23000'?'Já existe um cadastro com essas informações. Nenhum registro foi duplicado.':'Não foi possível concluir a operação.';}header('Location: '.url('admin/'));exit;}
$companies=$pdo->query('SELECT * FROM companies ORDER BY name')->fetchAll();$contracts=$pdo->query('SELECT ct.*,c.name company,c.slug company_slug,c.status company_status FROM contracts ct JOIN companies c ON c.id=ct.company_id ORDER BY c.name,ct.name')->fetchAll();$users=$pdo->query('SELECT u.*,c.name company FROM users u LEFT JOIN companies c ON c.id=u.company_id ORDER BY u.created_at DESC')->fetchAll();
function hidden():string{return '<input type="hidden" name="csrf" value="'.e(csrf()).'">';}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Administração | Newsiga</title><link rel="stylesheet" href="../assets/style.css?v=7.5.1"><link rel="stylesheet" href="../assets/admin.css?v=7.5.1"></head><body><header class="top"><a class="brand" href="<?=url('dashboard.php')?>">newsiga</a><nav><a href="<?=url('dashboard.php')?>">Painel</a><a href="<?=url('logout.php')?>">Sair</a></nav></header><main class="container"><div class="admin-heading"><div><p class="kicker">ADMINISTRAÇÃO</p><h1>Gestão de clientes</h1></div><div class="action-bar"><button onclick="openDialog('companyDialog')">+ Cadastrar empresa</button><button onclick="openDialog('contractDialog')">+ Cadastrar contrato</button><button class="primary" onclick="openDialog('userDialog')">+ Cadastrar usuário</button></div></div><?php if($msg):?><p class="success"><?=e($msg)?></p><?php endif;?><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?>
<div class="overview-grid"><section class="panel compact"><div class="section-title"><h2>Empresas</h2><span><?=count($companies)?> cadastradas</span></div><table><tr><th>Empresa</th><th>Situação</th></tr><?php foreach($companies as $c):?><tr><td><strong><?=e($c['name'])?></strong></td><td><span class="status active"><?=e($c['status'])?></span></td></tr><?php endforeach;?></table></section><section class="panel compact"><div class="section-title"><h2>Contratos</h2><span><?=count($contracts)?> cadastrados</span></div><table><tr><th>Empresa</th><th>Pacote</th><th>Valores</th><th></th></tr><?php foreach($contracts as $c):?><tr><td><strong><?=e($c['company'])?></strong><small><?=e($c['name'])?></small></td><td><?=number_format((float)$c['monthly_hours'],0,',','.')?>h</td><td><small>Base R$ <?=number_format((float)$c['base_amount'],2,',','.')?><br>Extra R$ <?=number_format((float)$c['excess_hour_amount'],2,',','.')?></small></td><td class="contract-actions"><a class="icon-btn" href="<?=url('relatorio.php?company_id='.(int)$c['company_id'])?>" target="_blank" rel="noopener">Relatório</a><button class="icon-btn" onclick="openDialog('contract<?=$c['id']?>')">Editar</button><form method="post" onsubmit="return confirm('Excluir este contrato?')"><?=hidden()?><input type="hidden" name="action" value="delete_contract"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="icon-btn danger">Excluir</button></form></td></tr><?php endforeach;?></table></section></div>
<section class="panel compact users"><div class="section-title"><h2>Usuários</h2><span><?=count($users)?> cadastrados</span></div><table><tr><th>Nome</th><th>E-mail</th><th>Empresa</th><th>Situação</th><th></th></tr><?php foreach($users as $u):?><tr><td><strong><?=e($u['name'])?></strong></td><td><?=e($u['email'])?></td><td><?=e($u['company']??'Newsiga')?></td><td><span class="status <?=$u['status']?>"><?=e($u['status'])?></span></td><td class="row-actions"><?php if($u['role']==='client'):?><button class="icon-btn" onclick="openDialog('editUser<?=$u['id']?>')">Editar</button><form method="post"><?=hidden()?><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="icon-btn"><?=$u['status']==='active'?'Bloquear':'Ativar'?></button></form><?php if($u['status']==='active'):?><form method="post"><?=hidden()?><input type="hidden" name="action" value="send_access"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="icon-btn">Enviar acesso</button></form><?php endif;?><button class="icon-btn" onclick="openDialog('password<?=$u['id']?>')">Redefinir senha</button><?php else:?><span class="admin-tag">Administrador</span><?php endif;?></td></tr><?php endforeach;?></table></section>
<dialog id="companyDialog"><button class="close" onclick="closeDialog(this)">×</button><p class="kicker">NOVO CADASTRO</p><h2>Cadastrar empresa</h2><form method="post"><?=hidden()?><input type="hidden" name="action" value="company"><label>Nome da empresa<input name="name" required></label><button class="button">Cadastrar empresa</button></form></dialog>
<dialog id="contractDialog"><button class="close" onclick="closeDialog(this)">×</button><p class="kicker">NOVO CADASTRO</p><h2>Cadastrar contrato</h2><form method="post"><?=hidden()?><input type="hidden" name="action" value="new_contract"><label>Empresa<select name="company_id" required><?php foreach($companies as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Nome do contrato<input name="name" required></label><div class="form-grid"><label>Pacote de horas<input name="hours" required></label><label>Valor-base<input name="base" required></label><label>Hora excedente<input name="excess" required></label><label>Dia da renovação<input name="renewal_day" type="number" min="1" max="28" value="1" required></label></div><label class="checkbox"><input name="cumulative" type="checkbox"> Horas cumulativas</label><button class="button">Cadastrar contrato</button></form></dialog>
<dialog id="userDialog"><button class="close" onclick="closeDialog(this)">×</button><p class="kicker">NOVO CADASTRO</p><h2>Cadastrar usuário</h2><form method="post"><?=hidden()?><input type="hidden" name="action" value="user"><label>Empresa<select name="company_id" required><?php foreach($companies as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Nome<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Senha provisória<input name="password" type="password" minlength="12" required></label><button class="button">Criar usuário</button></form></dialog>
<?php foreach($contracts as $c):?><dialog id="contract<?=$c['id']?>"><button class="close" onclick="closeDialog(this)">×</button><p class="kicker"><?=e($c['company'])?></p><h2>Editar contrato</h2><form method="post"><?=hidden()?><input type="hidden" name="action" value="contract"><input type="hidden" name="id" value="<?=$c['id']?>"><div class="form-grid"><label>Pacote<input name="hours" value="<?=e($c['monthly_hours'])?>"></label><label>Valor-base<input name="base" value="<?=number_format((float)$c['base_amount'],2,',','.')?>"></label><label>Hora excedente<input name="excess" value="<?=number_format((float)$c['excess_hour_amount'],2,',','.')?>"></label><label>Renovação<input name="renewal_day" type="number" min="1" max="28" value="<?=$c['renewal_day']?>"></label></div><label class="checkbox"><input name="cumulative" type="checkbox" <?=$c['cumulative']?'checked':''?>> Horas cumulativas</label><button class="button">Salvar alterações</button></form></dialog><?php endforeach;?>
<?php foreach($users as $u):if($u['role']!=='client')continue;?><dialog id="editUser<?=$u['id']?>"><button class="close" onclick="closeDialog(this)">×</button><p class="kicker">CADASTRO DO USUÁRIO</p><h2>Editar usuário</h2><form method="post"><?=hidden()?><input type="hidden" name="action" value="edit_user"><input type="hidden" name="id" value="<?=$u['id']?>"><label>Empresa<select name="company_id" required><?php foreach($companies as $c):?><option value="<?=$c['id']?>" <?=((int)$u['company_id']===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Nome<input name="name" value="<?=e($u['name'])?>" required></label><label>E-mail<input name="email" type="email" value="<?=e($u['email'])?>" required></label><button class="button">Salvar alterações</button></form></dialog><dialog id="password<?=$u['id']?>"><button class="close" onclick="closeDialog(this)">×</button><p class="kicker"><?=e($u['name'])?></p><h2>Redefinir senha</h2><form method="post"><?=hidden()?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="id" value="<?=$u['id']?>"><label>Nova senha provisória<input name="password" type="password" minlength="12" required></label><button class="button">Redefinir senha</button></form></dialog><?php endforeach;?><script>function openDialog(id){document.getElementById(id).showModal()}function closeDialog(btn){btn.closest('dialog').close()}document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}))</script></main></body></html>
